package com.maxhitcalc;

import com.google.common.collect.ImmutableSet;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemVariationMapping;

import java.util.Set;

public class EquipmentItems
{
    private static final Set<Integer> DIZANAS_QUIVER_IDS = ImmutableSet.<Integer>builder()
            .addAll(ItemVariationMapping.getVariations(ItemVariationMapping.map(ItemID.DIZANAS_QUIVER_CHARGED)))
            .addAll(ItemVariationMapping.getVariations(ItemVariationMapping.map(ItemID.DIZANAS_QUIVER_INFINITE)))
            .addAll(ItemVariationMapping.getVariations(ItemVariationMapping.map(ItemID.SKILLCAPE_MAX_DIZANAS)))
            .build();
    /**
     * Gets Currently Equipped Items
     *
     * @param client
     *
     * @return Item[] of all Equipped Items
     */
    public static Item[] getCurrentlyEquipped(Client client)
    {
        Item[] playerEquipment;
        if (client.getItemContainer(InventoryID.WORN) != null )
        {
            playerEquipment = client.getItemContainer(InventoryID.WORN).getItems();
        }
        else
        {
            playerEquipment = null;
        }

        return playerEquipment;
    }

    /**
     * Get Item Name in Specific Slot of Specified Equipment Set <br>
     *
     * @param client
     * @param ITEMSLOT the item slot id that will be checked
     * @param playerEquipment specified Item list
     * @return string of item name, returns empty string if ITEMSLOT is empty
     */
    public static String getItemNameInGivenSetSlot(Client client, Item[] playerEquipment, EquipmentInventorySlot ITEMSLOT)
    {
        String itemName = "";

        if(playerEquipment != null)
        {
            if(playerEquipment.length > ITEMSLOT.getSlotIdx()
                    && playerEquipment[ITEMSLOT.getSlotIdx()] != null)
            {
                itemName = client.getItemDefinition(playerEquipment[ITEMSLOT.getSlotIdx()].getId()).getName().toLowerCase();
            }
        }

        return itemName;
    }

    /**
     * Get Item ID in Specific Slot with a specified equipment list <br>
     *
     * @param playerEquipment specified Item list
     * @param ITEMSLOT the item slot id that will be checked
     *
     * @return int of item id, returns -1 if empty
     */
    public static int getItemIdInGivenSetSlot(Item[] playerEquipment, EquipmentInventorySlot ITEMSLOT)
    {
        int itemID = -1;

        if(playerEquipment != null)
        {
            if(playerEquipment.length > ITEMSLOT.getSlotIdx()
                    && playerEquipment[ITEMSLOT.getSlotIdx()] != null)
            {
                itemID = playerEquipment[ITEMSLOT.getSlotIdx()].getId();
            }
        }

        return itemID;
    }

    public static boolean isQuiverEquipped(Item[] playerEquipment)
    {
        int capeId = getItemIdInGivenSetSlot(playerEquipment, EquipmentInventorySlot.CAPE);
        return DIZANAS_QUIVER_IDS.contains(capeId);
    }

    public static Item getQuiverItem(Client client)
    {
        int ammoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
        int ammoAmount = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
        if (ammoId != -1 && ammoAmount > 0)
        {
            return new Item(ammoId, ammoAmount);
        }
        return null;
    }

    public static String getQuiverItemName(Client client)
    {
        String itemName = "";

        Item quiverItems = getQuiverItem(client);

        if (quiverItems != null)
        {
            itemName = client.getItemDefinition(quiverItems.getId()).getName().toLowerCase();
        }

        return itemName;
    }

    public static int getQuiverItemID(Client client)
    {
        int itemID = -1;

        Item quiverItems = getQuiverItem(client);

        if (quiverItems != null)
        {
            itemID = quiverItems.getId();

        }

        return itemID;
    }

    /**
     * Returns if a given ammo could be fired from a weapon,
     * does not take into account the tier of ammo or tier of weapon
     *
     * @param ammoTypeName name of ammo item
     * @param weaponName name of weapon
     *
     * @return boolean, true or false
     */
    public static boolean doesAmmoMatchWeapon(String ammoTypeName, String weaponName)
    {
        // Arrows -> bows
        if (ammoTypeName.contains("arrow"))
        {
            // Ogre arrow -> ogre bow
            if (ammoTypeName.contains("ogre"))
            {
                if(weaponName.contains("ogre")) return true;
            }
            // all other arrows -> any bow
            else
            {
                if(weaponName.contains("bow") && !weaponName.contains("crossbow")) return true;
            }
        }
        // Brutal Arrows
        else if(ammoTypeName.contains("brutal"))
        {
            if(weaponName.contains("ogre")) return true;
        }
        // Bolts -> crossbows
        else if(ammoTypeName.contains("bolts"))
        {
            // Kebbit bolts -> hunters' crossbow
            if(ammoTypeName.contains("kebbit"))
            {
                if(weaponName.contains("hunters' crossbow")) return true;
            }
            // Antler bolts -> hunter's sunlight crossbow
            else if(ammoTypeName.contains("antler"))
            {
                if(weaponName.contains("hunters' sunlight crossbow")) return true;
            }
            // Bone bolts -> Dorgeshuun crossbow
            else if (ammoTypeName.contains("bone"))
            {
                if(weaponName.contains("dorgeshuun")) return true;
            }
            // All other types of bolts -> normal crossbows
            else
            {
                if(weaponName.contains("crossbow")) return true;
            }
        }
        // Bolt rack -> Karil's
        else if(ammoTypeName.contains("rack"))
        {
            if(weaponName.contains("karil's")) return true;
        }
        // Javelin -> Ballista
        else if(ammoTypeName.contains("javelin"))
        {
            if(weaponName.contains("ballista")) return true;
        }
        // Tar -> Salamander or Swamp lizard
        else if(ammoTypeName.contains("tar"))
        {
            if(weaponName.contains("salamander") || weaponName.contains("lizard")) return true;
        }

        // otherwise, ammo does NOT match!
        return false;
    }
}

